void insert(int A[], int &n, int e, int k)
{
    for(int i = n - 1; i >= k; i--)
        A[i + 1] = A[i];
    A[k] = e;
    n++;
}

void detele(int A[], int &n, int k)
{
    for(int i = k + 1; i < n; i++)
        A[i - 1] = A[i];
    n--;
}

bool sequential_search(int A[], int n, int e)
{
    for (int i = 0; i < n; i++)
        if (A[i] == e)
            return true;

    return false;
}

bool binary_search(int A[], int n, int e)
{
    int left = 0, right = n - 1, m;

    while (left <= right)
    {
        m = (left + right) / 2;

        if (A[m] == e)
            return true;
        else if (A[m] < e)
            left = m + 1;
        else
            right = m - 1;
    }

    return false;
}

void BubbleSort(int A[], int n)
{
    int i, j, tmp;
    for (i = 1; i < n; i++)
        for (j = 1; j <= n - i; j++)
            if (A[j] < A[j - 1])
            {
                tmp = A[j];
                A[j] = A[j - 1];
                A[j - 1] = tmp;
            }
}

void merge_unsorted(int A[], int B[], int C[], int m, int n)
{
    int i;
    for (i = 0; i < m; i++)
        C[i] = A[i];
    for (i = 0; i < n; i++)
        C[m + i] = B[i];
}

void merge_unsorted(int A[], int B[], int C[], int m, int n)
{
    int i = 0, j = 0, k = 0;
    while (i < m && j < n)
    {
        if (A[i] < B[j])
            C[k++] = A[i++];
        else
            C[k++] = B[j++];
    }
    while (i < m)
        C[k++] = A[i++];
    while (j < n)
        C[k++] = B[j++];
}

#include <iostream>
#include <algorithm>

int main()
{
    int size;
    std::cout << "Enter the size of the array: ";
    std::cin >> size;

    int* arr = new int[size];
    int* ptr = arr;

    // Initialize array
    for (int i = 0; i < size; i++)
    {
        *ptr = i + 1;
        ptr++;
    }

    ptr = arr;

    std::cout << "Original array: ";
    for (int i = 0; i < size; i++)
    {
        std::cout << *ptr << " ";
        ptr++;
    }

    // Resize the array
    int new_size;
    std::cout << "\nEnter the new size of the array: ";
    std::cin >> new_size;

    int* new_arr = new int[new_size];

    // Copy the elements to the new array
    for (int i = 0; i < std::min(size, new_size); i++)
    {
        new_arr[i] = arr[i];
    }

    ptr = new_arr;

    std::cout << "Array after resizing: ";
    for (int i = 0; i < new_size; i++)
    {
        std::cout << *ptr << " ";
        ptr++;
    }

    // Free the memory
    delete[] arr;
    delete[] new_arr;

    return 0;
}

